import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [monthlyData, setMonthlyData] = useState([]);
  const [recentCustomers, setRecentCustomers] = useState([]);

  useEffect(() => {
    loadDashboard();
  }, []);

  const loadDashboard = async () => {
    try {
      setLoading(true);
      const res = await API.get('/dashboard');
      setStats(res.data.data.stats);
      setMonthlyData(res.data.data.monthlyData);
      setRecentCustomers(res.data.data.recentCustomers);
    } catch (error) {
      toast.error('Failed to load dashboard data');
      console.error('Dashboard error:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading dashboard...</div>;
  }

  if (!stats) {
    return <div className="loading">No data available</div>;
  }

  const statCards = [
    { label: 'Total Customers', value: stats.totalCustomers, color: '#2a7de1' },
    { label: 'Active', value: stats.active, color: '#28a745' },
    { label: 'Cut Off', value: stats.cutOff, color: '#dc3545' },
    { label: 'Disable', value: stats.disable, color: '#6c757d' },
    { label: 'Paid', value: stats.paid, color: '#28a745' },
    { label: 'Unpaid', value: stats.unpaid, color: '#dc3545' },
    { label: 'Total Revenue', value: `PKR ${stats.totalRevenue.toLocaleString()}`, color: '#2a7de1' },
    { label: 'Total Dues', value: `PKR ${stats.totalDues.toLocaleString()}`, color: '#dc3545' },
    { label: 'Collected', value: `PKR ${stats.collected.toLocaleString()}`, color: '#28a745' },
    { label: 'Pending Collection', value: `PKR ${stats.pendingCollection.toLocaleString()}`, color: '#fd7e14' },
    { label: 'Total Expenses', value: `PKR ${stats.totalExpenses.toLocaleString()}`, color: '#dc3545' },
    { label: 'Net Profit', value: `PKR ${stats.netProfit.toLocaleString()}`, color: stats.netProfit >= 0 ? '#28a745' : '#dc3545' },
  ];

  return (
    <div>
      <h2 style={{ marginBottom: '20px' }}>Dashboard Overview</h2>

      {/* Stats Grid */}
      <div style={styles.grid}>
        {statCards.map((card, index) => (
          <div key={index} style={styles.card}>
            <div style={styles.cardLabel}>{card.label}</div>
            <div style={{ ...styles.cardValue, color: card.color }}>{card.value}</div>
          </div>
        ))}
      </div>

      {/* Monthly Chart */}
      <div style={styles.chartSection}>
        <h3 style={styles.sectionTitle}>Monthly Revenue & Customers</h3>
        <div style={styles.chartContainer}>
          {monthlyData.map((item) => (
            <div key={item.month} style={styles.chartBarWrapper}>
              <div style={styles.chartBar}>
                <div
                  style={{
                    ...styles.barRevenue,
                    height: `${(item.revenue / (Math.max(...monthlyData.map(d => d.revenue)) || 1)) * 100}%`,
                  }}
                />
                <div
                  style={{
                    ...styles.barCustomers,
                    height: `${(item.customers / (Math.max(...monthlyData.map(d => d.customers)) || 1)) * 100}%`,
                  }}
                />
              </div>
              <div style={styles.chartLabel}>{item.month}</div>
            </div>
          ))}
        </div>
        <div style={styles.chartLegend}>
          <span><span style={{ ...styles.legendDot, background: '#2a7de1' }} /> Revenue</span>
          <span><span style={{ ...styles.legendDot, background: '#28a745' }} /> Customers</span>
        </div>
      </div>

      {/* Recent Customers */}
      <div style={styles.recentSection}>
        <h3 style={styles.sectionTitle}>Recent Customers</h3>
        <table style={styles.table}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Customer ID</th>
              <th>Monthly Fee</th>
              <th>Status</th>
              <th>Payment</th>
            </tr>
          </thead>
          <tbody>
            {recentCustomers.length === 0 ? (
              <tr><td colSpan="5" style={{ textAlign: 'center', padding: '20px', color: '#6b7f99' }}>No customers found</td></tr>
            ) : (
              recentCustomers.map((c) => (
                <tr key={c._id}>
                  <td><strong>{c.name}</strong></td>
                  <td>{c.customerId}</td>
                  <td>PKR {c.monthlyFee.toLocaleString()}</td>
                  <td>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.status === 'Active' ? '#d4edda' : c.status === 'Cut Off' ? '#f8d7da' : '#e2e3e5',
                      color: c.status === 'Active' ? '#155724' : c.status === 'Cut Off' ? '#721c24' : '#383d41',
                    }}>
                      {c.status}
                    </span>
                  </td>
                  <td>
                    <span style={{
                      ...styles.statusBadge,
                      background: c.paymentStatus === 'Paid' ? '#d4edda' : c.paymentStatus === '1 YEAR ADVANCED' ? '#cce5ff' : '#f8d7da',
                      color: c.paymentStatus === 'Paid' ? '#155724' : c.paymentStatus === '1 YEAR ADVANCED' ? '#004085' : '#721c24',
                    }}>
                      {c.paymentStatus}
                    </span>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const styles = {
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '16px',
    marginBottom: '24px',
  },
  card: {
    background: 'white',
    padding: '16px 20px',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
    boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
  },
  cardLabel: {
    fontSize: '12px',
    fontWeight: '500',
    color: '#6b7f99',
    textTransform: 'uppercase',
    letterSpacing: '0.3px',
  },
  cardValue: {
    fontSize: '24px',
    fontWeight: '700',
    marginTop: '4px',
  },
  chartSection: {
    background: 'white',
    padding: '24px',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
    marginBottom: '24px',
  },
  sectionTitle: {
    fontSize: '16px',
    marginBottom: '16px',
    color: '#1a2a3a',
  },
  chartContainer: {
    display: 'flex',
    alignItems: 'flex-end',
    justifyContent: 'space-around',
    height: '200px',
    gap: '8px',
  },
  chartBarWrapper: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    flex: 1,
  },
  chartBar: {
    display: 'flex',
    alignItems: 'flex-end',
    gap: '4px',
    height: '160px',
    width: '100%',
    maxWidth: '40px',
  },
  barRevenue: {
    width: '16px',
    background: '#2a7de1',
    borderRadius: '4px 4px 0 0',
    transition: 'height 0.5s ease',
    minHeight: '4px',
  },
  barCustomers: {
    width: '16px',
    background: '#28a745',
    borderRadius: '4px 4px 0 0',
    transition: 'height 0.5s ease',
    minHeight: '4px',
  },
  chartLabel: {
    fontSize: '10px',
    color: '#6b7f99',
    marginTop: '4px',
    fontWeight: '500',
  },
  chartLegend: {
    display: 'flex',
    justifyContent: 'center',
    gap: '24px',
    marginTop: '12px',
    fontSize: '13px',
    color: '#1a2a3a',
  },
  legendDot: {
    display: 'inline-block',
    width: '12px',
    height: '12px',
    borderRadius: '3px',
    marginRight: '6px',
  },
  recentSection: {
    background: 'white',
    padding: '24px',
    borderRadius: '12px',
    border: '1px solid #e9eef4',
  },
